import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"VS Code Extension","description":"","frontmatter":{},"headers":[],"relativePath":"guide/vscode-extension.md","filePath":"guide/vscode-extension.md","lastUpdated":1793550481000}'),i={name:"guide/vscode-extension.md"};function o(l,e,h,r,d,c){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="vs-code-extension" tabindex="-1">VS Code Extension <a class="header-anchor" href="#vs-code-extension" aria-label="Permalink to &quot;VS Code Extension&quot;">​</a></h1><p>By the end of this page the extension is installed, you have walked through its onboarding, and the MCP Lens icon in the activity bar shows your own cost x usage matrix. This is the main distribution path: scanning, hook installation, reports and dependency analysis all live inside the extension, so no separate CLI install is needed.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Node.js 20 or later.</li><li>VS Code 1.90 or later.</li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>The extension is not published to the VS Code Marketplace yet. Build the <code>.vsix</code> yourself and install it locally.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/seodduu/MCPLens.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MCPLens</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-context-lens</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # creates packages/extension/*.vsix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-extension</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/extension/mcp-context-lens-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.vsix</span></span></code></pre></div><p>Substitute <code>&lt;version&gt;</code> with whatever version <code>npm run package</code> printed into the <code>.vsix</code> file name. <code>code --install-extension</code> prints a line confirming the extension was installed successfully.</p><h2 id="run-the-onboarding-walkthrough" tabindex="-1">Run the onboarding walkthrough <a class="header-anchor" href="#run-the-onboarding-walkthrough" aria-label="Permalink to &quot;Run the onboarding walkthrough&quot;">​</a></h2><p>Reopen VS Code. The MCP Lens icon appears in the activity bar, and the onboarding walkthrough opens automatically. It has four steps, in order:</p><ol><li><strong>Scan</strong> the MCP servers configured for your clients, to measure how many tokens each tool definition costs.</li><li><strong>Install hooks</strong> for the clients you use, so real call counts start replacing the zeros in the report.</li><li><strong>Dependency analysis</strong>, which asks an LLM to judge which tools are safe to filter or remove given the servers actually attached (see the consent choice below before this step runs).</li><li><strong>Enable global actions</strong>, which lets the extension edit a client config file to turn tools off, once you explicitly allow it.</li></ol><p>Once onboarding is done, the activity bar icon holds two views: <code>Cost × Usage Matrix</code> and <code>Setup Status</code>.</p><h2 id="choose-how-much-runs-automatically" tabindex="-1">Choose how much runs automatically <a class="header-anchor" href="#choose-how-much-runs-automatically" aria-label="Permalink to &quot;Choose how much runs automatically&quot;">​</a></h2><p>The last onboarding step asks one question: should the extension handle a newly attached MCP server on its own from now on? There are three choices:</p><ul><li>Leave both scanning and dependency analysis to it.</li><li>Leave only scanning to it, and run the analysis yourself (analysis spends LLM tokens, so some people would rather trigger it deliberately).</li><li>Do both yourself.</li></ul><p>Nothing runs automatically before you answer this question. Once it is on, only servers you attach afterward are picked up automatically; it reuses the consent already on file and does not ask again. Withdraw consent at any time with the <code>MCP Lens: Withdraw Inference Consent</code> command, which also stops the automatic analysis. Automatic scanning and automatic analysis can be turned off individually with the <code>mcpLens.autoScan</code> and <code>mcpLens.autoAnalyze</code> settings.</p><h2 id="what-stays-local" tabindex="-1">What stays local <a class="header-anchor" href="#what-stays-local" aria-label="Permalink to &quot;What stays local&quot;">​</a></h2><p>Everything is stored in <code>~/.mcplens/lens.db</code> (SQLite) on your machine. MCP Lens collects session, turn and call IDs, the client name, server and tool names, observation time, call duration and whether a call errored, plus the token counts of the scanned tool definitions. It never collects conversation bodies, prompts, tool inputs, tool responses, assistant response bodies or source code. The only feature that leaves your machine is dependency analysis, which sends only tool definitions and aggregated usage counts to the LLM provider you picked in walkthrough step 3.</p><p>Original client logs are always read-only: MCP Lens never modifies or moves them.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>To turn the <code>calls</code> column from zero into real numbers, install hooks for <a href="/MCPLens/guide/claude-code">Claude Code</a>, <a href="/MCPLens/guide/codex">Codex</a> or <a href="/MCPLens/guide/gemini-cli">Gemini CLI</a>, or use the <code>MCP Lens: Install Hooks for All Clients</code> command from inside the extension to do all of them at once. To understand every column and recommendation in the matrix, see <a href="/MCPLens/guide/reading-reports">Reading Reports</a>. For what a scan does under the hood, see <a href="/MCPLens/concepts/how-it-works">How It Works</a>.</p>`,21)])])}const k=s(i,[["render",o]]);export{u as __pageData,k as default};
